// Catmull-Rom through the points as cubic Béziers (for drawing), plus a fine polyline (for splitting the character).
function curves(p) {
  var segs = [];
  for (var i = 0; i < p.length - 1; i++) {
    var a = p[i - 1] || p[i], b = p[i], c = p[i + 1], e = p[i + 2] || c;
    segs.push([b, [b[0] + (c[0] - a[0]) / 6, b[1] + (c[1] - a[1]) / 6], [c[0] - (e[0] - b[0]) / 6, c[1] - (e[1] - b[1]) / 6], c]);
  }
  return segs;
}
function smooth(p) {
  return 'M' + p[0][0] + ' ' + p[0][1] + curves(p).map(function (s) {
    return 'C' + s[1].map(function (v) { return v.toFixed(1); }).join(' ') + ' ' + s[2].map(function (v) { return v.toFixed(1); }).join(' ') + ' ' + s[3].join(' ');
  }).join('');
}
function sample(p) {
  var out = [];
  curves(p).forEach(function (s) {
    for (var k = 0; k <= 12; k++) {
      var t = k / 12, u = 1 - t;
      out.push([u*u*u*s[0][0] + 3*u*u*t*s[1][0] + 3*u*t*t*s[2][0] + t*t*t*s[3][0], u*u*u*s[0][1] + 3*u*u*t*s[1][1] + 3*u*t*t*s[2][1] + t*t*t*s[3][1]]);
    }
  });
  return out;
}
function segDist(x, y, a, b) {
  var dx = b[0] - a[0], dy = b[1] - a[1], L = dx * dx + dy * dy, t = L ? Math.max(0, Math.min(1, ((x - a[0]) * dx + (y - a[1]) * dy) / L)) : 0;
  var px = a[0] + t * dx - x, py = a[1] + t * dy - y; return Math.sqrt(px * px + py * py);
}

