var MASKS = { song: PRE.masks };
function brushWidth(s) { return Math.round(s.t * 1.4 + 70); }
var PLATE_EDGE = PRE.plate, SOAK = PRE.soak;

// Written: the outline as the character 口 is written. The left side is the plate itself; then the top, a turn at the
// corner, the right side; then the bottom.
var W_PATHS = ['M48 6H90A4 4 0 0 1 94 10', 'M94 10V90A4 4 0 0 1 90 94', 'M48 94H91'];
// Carved: the frame cut one side at a time.
var C_PATHS = ['M6 10A4 4 0 0 1 10 6H90', 'M90 6A4 4 0 0 1 94 10V90', 'M94 90A4 4 0 0 1 90 94H10', 'M10 94A4 4 0 0 1 6 90V10'];
// Aged wear: paper-coloured chips that bite into the outer rim.
var CHIPS = ['M2.2 36.6l2.4-.8 1.3 1.7-.5 2.3-2.8.2z', 'M60.6 97.6l.4-2.4 1.9-.4 1.6 1.4-.6 1.8z', 'M97.6 18.2l-2.3.3-.7 1.9 1.2 1.6 1.9-.5z',
             'M2 73.6l2.6-.4 .9 1.6-1.1 1.7-2.4-.3z', 'M30.6 2.2l.5 2.4 1.7.6 1.3-1.2-.6-2z', 'M97.8 62.4l-2.4-.2-.8 1.8 1 1.7 2.1-.4z', 'M18 97.8l.6-2.3 1.4-.3 1 1.3-.5 1.6z'];

function sealSVG(id) {
  var sc = SCRIPT, masks = MASKS[SCRIPT_NAME], defs = '', ink = '', cut = '';
  CELLS.forEach(function (cell, i) {
    var g = sc.glyphs[cell.c], pl = sc.place(cell);
    defs += '<clipPath id="' + id + '-c' + i + '"><path transform="' + sc.flip + '" d="' + g.d + '"/></clipPath>';
    sc.strokes[cell.c].forEach(function (s, k) {
      defs += '<mask id="' + id + '-m' + i + '-' + k + '" maskUnits="userSpaceOnUse" x="0" y="0" width="' + sc.box + '" height="' + sc.box + '">' +
        '<image href="' + masks[cell.c][k] + '" x="0" y="0" width="' + sc.box + '" height="' + sc.box + '" preserveAspectRatio="none"/></mask>';
    });
    var html = '<g transform="translate(' + pl.tx.toFixed(3) + ' ' + pl.ty.toFixed(3) + ') scale(' + pl.k + ')">' +
      '<g class="brushes" data-i="' + i + '" data-cut="' + cell.cut + '" clip-path="url(#' + id + '-c' + i + ')" fill="none">' +
        sc.strokes[cell.c].map(function (s, k) {
          return '<path class="stk" mask="url(#' + id + '-m' + i + '-' + k + ')" data-w="' + brushWidth(s) + '" d="' + smooth(s.p) + '"/>';
        }).join('') +
      '</g>' +
      '<path class="whole" data-i="' + i + '" data-cut="' + cell.cut + '" transform="' + sc.flip + '" d="' + g.d + '"/>' +
    '</g>';
    if (cell.cut) cut += html; else ink += html;
  });
  // Plate mask: the brush edge (Written) and the soaking stages (Carved). Normally the edge strip covers everything.
  defs += '<mask id="' + id + '-plate" maskUnits="userSpaceOnUse" x="-10" y="-10" width="120" height="120">' +
    '<image class="platefill" href="' + PLATE_EDGE + '" x="-10" y="-100" width="120" height="300" preserveAspectRatio="none"/>' +
    SOAK.map(function (src, k) { return '<image class="soak" opacity="0" href="' + src + '" x="-10" y="-10" width="120" height="120" preserveAspectRatio="none"/>'; }).join('') + '</mask>';
  // Rock mask: full ink normally; for the rocked stamp, the four ink maps fade in one after another.
  defs += '<mask id="' + id + '-rock" maskUnits="userSpaceOnUse" x="-10" y="-10" width="120" height="120"><rect class="rockfull" x="-10" y="-10" width="120" height="120" fill="#fff"/>' +
    '</mask>';
  var fw = sc.frameW, aged = WEAR === 'aged';
  var line = function (cls, d) { return '<path class="' + cls + '" d="' + d + '" fill="none" stroke-width="' + fw + '" stroke-linecap="round"/>'; };
  return '<svg class="seal" viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false"><defs>' + INK_FILTER(id) + defs + '</defs>' +
    '<g class="all" filter="url(#' + id + '-ink)"' + (aged ? ' transform="rotate(-1.2 50 50)"' : '') + '><g class="inked" mask="url(#' + id + '-rock)">' +
      '<path class="frame" d="' + FRAME + '" fill="none" stroke-width="' + fw + '"/>' +
      W_PATHS.map(function (d) { return line('wf', d); }).join('') + C_PATHS.map(function (d) { return line('cf', d); }).join('') +
      '<g class="plategrp" mask="url(#' + id + '-plate)"><path class="half" d="' + HALF + '"/>' + cut + '</g>' + ink +
      (aged ? '<g class="chips">' + CHIPS.map(function (c) { return '<path d="' + c + '"/>'; }).join('') + '</g>' : '') +
    '</g></g></svg>';
}

// Colours come from the palette, so the page can switch between cinnabar on paper and gold on oxblood.
function paint(svg) {
  svg.querySelectorAll('.frame, .wf, .cf').forEach(function (w) { w.setAttribute('stroke', PAL.ink); });
  svg.querySelector('.half').setAttribute('fill', PAL.ink);
  svg.querySelectorAll('.whole').forEach(function (w) { w.setAttribute('fill', w.dataset.cut === 'true' ? PAL.ground : PAL.ink); });
  svg.querySelectorAll('.brushes').forEach(function (g) { g.setAttribute('stroke', g.dataset.cut === 'true' ? PAL.ground : PAL.ink); });
  var ch = svg.querySelector('.chips'); if (ch) ch.setAttribute('fill', PAL.ground);
}

// Easing: Tim's standard curve cubic-bezier(0.25, 0.1, 0.25, 1), solved numerically.
function bezier(x1, y1, x2, y2) {
  function at(a, b, t) { return 3 * a * t * (1 - t) * (1 - t) + 3 * b * t * t * (1 - t) + t * t * t; }
  return function (x) {
    if (x <= 0) return 0; if (x >= 1) return 1;
    var lo = 0, hi = 1, t = x;
    for (var k = 0; k < 24; k++) { t = (lo + hi) / 2; if (at(x1, x2, t) < x) lo = t; else hi = t; }
    return at(y1, y2, t);
  };
}
var EASE = bezier(0.25, 0.1, 0.25, 1), LINEAR = function (t) { return t; }, INOUT = bezier(0.45, 0, 0.55, 1), HAND = bezier(0.4, 0, 0.6, 1);
function mix(a, b, t) {
  var pa = [1, 3, 5].map(function (k) { return parseInt(a.substr(k, 2), 16); }), pb = [1, 3, 5].map(function (k) { return parseInt(b.substr(k, 2), 16); });
  return '#' + pa.map(function (v, k) { return ('0' + Math.round(v + (pb[k] - v) * t).toString(16)).slice(-2); }).join('');
}

// One clock per seal. A track is {start, dur, ease, set(progress)}; a track with start -1 is applied once, before the clock starts.
function run(svg, tracks) {
  var token = svg._token = {}, t0 = null, end = 0;
  tracks.forEach(function (k) { end = Math.max(end, k.start + k.dur); });
  svg._tracks = tracks;
  function tick(now) {
    if (svg._token !== token) return;
    if (t0 === null) t0 = now;
    var t = (now - t0) * SPEED;
    seek(svg, t);
    if (t < end) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
  return end;
}
